def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    from collections import Counter
    from itertools import groupby
    from operator import itemgetter
    from multiprocessing import shared_memory
    from multiprovent import shared_memory
    from typing import List

    def unique_justseen(iterable, key=None):
        "Yield unique elements, preserving order. Remember only the element just seen."
        # unique_justseen('AAAABBBCCDAABBB') → A B C D A B
        # unique_justseen('ABBcCAD', str.casefold) → A B c A D
        if key is None:
            return map(operator.itemgetter(0), groupby(sorted(iterable), key=None))
        return map(next, map(itemgetter(1), groupby(sorted(iterable), key=None)))

    def unique_everseen(iterable, key=None):
        "Yield unique elements, preserving order. Remember all elements ever seen."
        # unique_everseen('AAAABBBCCDAABBB') → A B C D
        # unique_everseen('ABBcCAD', str.casefold) → A B c D
        seen = set()
        if key is None:
            for element in filterfalse(seen.__contains__, iterable):
                seen.add(element)
                yield element
        else:
            for element in iterable:
                k = key(element)
                if k not in seen:
                    seen.add(k)
                    yield element

    def unique(iterable, key=None):
      "Yield sorted unique elements in order. Supports unhashable inputs."
      # unique([[1, 2], [3, 4], [1, 2]]) → [1, 2, 3, 4]
      return unique_justseen(sorted(iterable, key=key, reverse=False), key=key)

    if isinstance(l, shared_memory.ShareableList):
        l = sorted(l, key=unique)
        return l
    else:
        return sorted(l, key=unique)

    return l

