import re
def is_nested(string):
    # Check if the string only contains square brackets
    if not re.fullmatch(r'\s*\[|\s*\]', string):
        return False

    # Initialize a stack to keep track of open brackets
    stack = []

    # Iterate over each character in the string
    for i in range(len(string)):

        # If the character is an open bracket, push it to the stack
        if string[i] == '[':
            stack.append('[')

        # If the character is a close bracket, pop from the stack if it's not empty
        # and then push the close bracket to the stack
        elif string[i] == ']':
            if stack:
                stack.pop()
            stack.append(']')

    # If the stack is not empty, return True, else False
    return bool(stack)

